protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>().HasIndex(p => p.Sku);
    modelBuilder.Entity<Product>().ToContainer("Products");

    // EF Core 9 changed the default discriminator property from "Discriminator" to "$type".
    // Preserve the EF Core 8 property name so existing 500K documents remain readable
    // and raw SQL queries referencing c.Discriminator keep working.
    modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

    // EF Core 9 changed the default id format from "EntityType|KeyValue" to just the key.
    // Preserve the EF Core 8 "Product|{Id}" format for compatibility with existing documents.
    modelBuilder.Entity<Product>().HasPartitionKey(p => p.Id);
    modelBuilder.Entity<Product>().Property(p => p.Id)
        .ToJsonProperty("id")
        .HasValueGenerator<LegacyCosmosIdGenerator>();
}

