class CosmosQuery
{
    // EF Core 9 Cosmos provider removed synchronous APIs (ToList, First, etc.).
    // All queries must use their async counterparts.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — safe because we preserved "Discriminator" in OnModelCreating.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // Sync LINQ APIs (ToList, First, Single, etc.) are no longer supported
        // by the EF Core 9 Cosmos provider. Use the async versions instead.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

